commit ecdeee95d1fadacc1705d904855842d80458ea4f
Author: Frederic Thomas <webdoublefx@gmail.com>
Date:   Sun Aug 9 10:45:11 2026 +0100

    debugger: stop naming a wrong cause for an absent transcript

    The per-transcript absent line rendered "not captured (may have been pruned
    by the >30-day cleanup)" unconditionally, for any missing transcript file.

    The AuditReport carries no run timestamp, so that line cannot distinguish a
    genuinely pruned transcript from one that never existed. Measured on a
    minutes-old run: a scripted-stage call errored (opencode SQLite lock) before
    writing anything, and the report told the reader a specific, plausible,
    wrong cause for the absence.

    Names no cause now. The empty-list message is left as is: it already offers
    both possibilities without picking one.

    The new lock asserts the property over EVERY absent line rather than the one
    line this fix touched, and was proven red against the reinstated defect.
    Committed debugger bins rebuilt (report-format is bundled into wt-stop-hook).

diff --git a/plugin/bin/wt-stop-hook.mjs b/plugin/bin/wt-stop-hook.mjs
index 6762a445..9e502d62 100644
--- a/plugin/bin/wt-stop-hook.mjs
+++ b/plugin/bin/wt-stop-hook.mjs
@@ -1001,7 +1001,7 @@ function formatAuditReportMarkdown(r, ctx = {}) {
   } else {
     for (const t of r.transcripts) {
       lines.push(
-        t.present ? `- \u2713 ${t.relativePath}` : `- \u2717 ${t.relativePath} \u2014 not captured (may have been pruned by the >30-day cleanup)`
+        t.present ? `- \u2713 ${t.relativePath}` : `- \u2717 ${t.relativePath} \u2014 not captured (no transcript file; cause not recorded)`
       );
     }
   }
diff --git a/toolkit/bin/wt-stop-hook.mjs b/toolkit/bin/wt-stop-hook.mjs
index 6762a445..9e502d62 100644
--- a/toolkit/bin/wt-stop-hook.mjs
+++ b/toolkit/bin/wt-stop-hook.mjs
@@ -1001,7 +1001,7 @@ function formatAuditReportMarkdown(r, ctx = {}) {
   } else {
     for (const t of r.transcripts) {
       lines.push(
-        t.present ? `- \u2713 ${t.relativePath}` : `- \u2717 ${t.relativePath} \u2014 not captured (may have been pruned by the >30-day cleanup)`
+        t.present ? `- \u2713 ${t.relativePath}` : `- \u2717 ${t.relativePath} \u2014 not captured (no transcript file; cause not recorded)`
       );
     }
   }
diff --git a/toolkit/packages/debugger/src/report-format.ts b/toolkit/packages/debugger/src/report-format.ts
index de04915f..310182f1 100644
--- a/toolkit/packages/debugger/src/report-format.ts
+++ b/toolkit/packages/debugger/src/report-format.ts
@@ -244,7 +244,11 @@ export function formatAuditReportMarkdown(r: AuditReport, ctx: AuditFormatContex
       lines.push(
         t.present
           ? `- ✓ ${t.relativePath}`
-          : `- ✗ ${t.relativePath} — not captured (may have been pruned by the >30-day cleanup)`,
+          // Deliberately names NO cause. The report has no run timestamp, so it cannot tell a
+          // pruned transcript (>30-day cleanup) from one that never existed — an agent whose
+          // call errored before writing anything leaves the same absence. Naming the cleanup
+          // here told readers a specific, plausible, wrong cause on minutes-old runs.
+          : `- ✗ ${t.relativePath} — not captured (no transcript file; cause not recorded)`,
       )
     }
   }
diff --git a/toolkit/packages/debugger/test/report-format.test.ts b/toolkit/packages/debugger/test/report-format.test.ts
index 2dfbb29b..0d8f287e 100644
--- a/toolkit/packages/debugger/test/report-format.test.ts
+++ b/toolkit/packages/debugger/test/report-format.test.ts
@@ -91,11 +91,29 @@ describe('formatAuditReportMarkdown — honest empty states', () => {
     expect(md).toMatch(/no transcripts|pruned/i)
   })

-  it('marks each transcript present/absent with the cleanup note for absent ones', () => {
+  it('marks each transcript present/absent', () => {
     const md = formatAuditReportMarkdown(report())
     expect(md).toContain('transcripts/agent-ac83de77485e77ad1.jsonl')
     expect(md).toContain('transcripts/agent-a29e57ea76ae2941e.jsonl')
-    expect(md).toMatch(/pruned|not captured/i)
+    expect(md).toMatch(/not captured/i)
+  })
+
+  // The report carries no run timestamp, so a per-transcript line CANNOT distinguish a pruned
+  // transcript from one that never existed (the agent's call errored before writing). Naming
+  // the >30-day cleanup on that line asserted a specific, wrong cause on minutes-old runs.
+  // Lock the property over EVERY absent line, not the one line this fix happened to touch.
+  it('names no cause on a per-transcript absent line', () => {
+    const md = formatAuditReportMarkdown(
+      report({
+        transcripts: [
+          { agentId: 'a1', relativePath: 'transcripts/agent-a1.jsonl', present: false },
+          { agentId: 'a2', relativePath: 'transcripts/agent-a2.jsonl', present: false },
+        ],
+      }),
+    )
+    const absentLines = md.split('\n').filter((l) => l.startsWith('- ✗ transcripts/'))
+    expect(absentLines).toHaveLength(2)
+    for (const line of absentLines) expect(line).not.toMatch(/prune|cleanup|30-day/i)
   })
 })

